{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create Or Replace Table zeproc_db.maplemonk.Zeproc_db_Magento_Sales_Fact_items as Select SOI.SKU, SOI.Name as Product_Name, SOI.PRODUCT_TYPE, SOI.ITEM_ID, SOI.PRODUCT_ID, SOI.QTY_ORDERED, SOI.QTY_SHIPPED, SOI.QTY_CANCELED, SOI.QTY_INVOICED, SOI.QTY_REFUNDED, SOI.Order_id, tr.channel, tr.SESSIONCAMPAIGNNAME, SOI.store_id, SOI.CREATED_AT::timestamp as CREATED_AT, SOI.UPDATED_AT , SOI.BASE_PRICE, SOI.PRICE_INCL_TAX, ifnull(SOI.PRICE_INCL_TAX,0) + ifnull(DIV0(ifnull(SO.BASE_SHIPPING_INCL_TAX,0),count(*) over(partition by soi.order_id)),0) as total_Sales, SO.INCREMENT_ID as Reference_code, SO.STATE, SO.STATUS, SO.STORE_CURRENCY_CODE, SO.STORE_NAME, SO.CUSTOMER_EMAIL, SO.CUSTOMER_FIRSTNAME, SO.CUSTOMER_LASTNAME, SO.CUSTOMER_MIDDLENAME, SO.SHIPPING_CANCELED, SO.SHIPPING_METHOD, sii.qty AS Sii_qty_invoiced, si.increment_id AS invoice_number, si.created_at AS invoice_date, scmi.qty AS scm_qty_refunded, ifnull(scmi.PRICE_INCL_TAX,0) + ifnull(DIV0(ifnull(SO.SHIPPING_TAX_REFUNDED,0),count(*) over(partition by soi.order_id)),0) + ifnull(DIV0(ifnull(SO.SHIPPING_REFUNDED,0),count(*) over(partition by soi.order_id)),0) as refund_price, scmi.row_total AS refund_row_total, scm.increment_id AS creditmemo_number, scm.created_at AS creditmemo_date, scm.state AS creditmemo_status, sop.method AS payment_method, sop.additional_information, sop.amount_paid, soa.firstname, soa.company, soa.lastname, soa.street, soa.city, soa.region, soa.postcode, soa.country_id, soa.telephone, brand ,googleshopping_exclude ,model_number ,d.name catalogue_name ,parent_sku ,d.price catalogue_price ,size ,supplier_name ,supplier_product_url ,type ,unspsc ,visibility ,category_ids ,CATEGORY_ID_NEW ,special_price ,Updated_price ,Updated_TAX_AMOUNT ,UPdated_PRICE_INCL_TAX ,ifnull(DIV0(ifnull(SO.SHIPPING_TAX_AMOUNT,0),count(*) over(partition by soi.order_id)),0) as SHIPPING_TAX_AMOUNT ,ifnull(DIV0(ifnull(SO.SHIPPING_AMOUNT,0),count(*) over(partition by soi.order_id)),0) as SHIPPING_AMOUNT ,ifnull(DIV0(ifnull(sp.spend,0),count(*) over(partition by lower(soi.product_id::string),soi.created_at::date,lower(trim(tr.channel)),upper(replace(tr.SESSIONCAMPAIGNNAME,\' \',\'\')))),0) as Spend from ( select sc.*,coalesce(soI.price,sc.price) as Updated_price ,coalesce(soI.product_id,sc.product_id) as Updated_product_Id ,coalesce(soI.TAX_AMOUNT,sc.TAX_AMOUNT) Updated_TAX_AMOUNT ,coalesce(soI.PRICE_INCL_TAX,sc.PRICE_INCL_TAX) UPdated_PRICE_INCL_TAX from (select * from zeproc_db.maplemonk.zeproc_magento_sales_order_item where lower(product_type) = \'simple\' )sc left join ( Select * from ( select order_id, ITEM_ID, product_id, sum(ifnull(price,0)) price , sum(ifnull(TAX_AMOUNT,0)) TAX_AMOUNT, sum(ifnull(PRICE_INCL_TAX,0)) PRICE_INCL_TAX, from zeproc_db.maplemonk.zeproc_magento_sales_order_item where lower(product_type) != \'simple\' group by 1,2,3 ) qualify row_number() over(partition by order_id,ITEM_ID order by 1) = 1 )SOI on sc.order_id = soi.order_id and sc.PARENT_ITEM_ID = soi.ITEM_ID )SOI LEFT JOIN( Select * from zeproc_db.maplemonk.zeproc_magento_sales_order Qualify row_number() over(partition by entity_id Order by 1) =1 )so ON soi.order_id = so.entity_id LEFT JOIN ( select * from zeproc_db.maplemonk.zeproc_magento_sales_invoice Qualify row_number() over(partition by order_id Order by 1) =1 ) AS si ON si.order_id = so.entity_id LEFT JOIN ( Select sii.*,si.order_id from zeproc_db.maplemonk.zeproc_magento_sales_invoice_item sii left join ( select entity_id,order_id from zeproc_db.maplemonk.zeproc_magento_sales_invoice qualify row_number() over(partition by entity_id order by 1) = 1 )si on si.entity_id = sii.parent_id qualify row_number() over(partition by product_id,order_id order by 1) = 1 )AS sii ON sii.product_id = soi.updated_product_id AND sii.order_id = soi.order_id LEFT JOIN( select * from zeproc_db.maplemonk.zeproc_magento_sales_creditmemo_item qualify row_number() over(partition by order_item_id order by 1) = 1 )AS scmi ON scmi.order_item_id = soi.item_id LEFT JOIN ( select * from zeproc_db.maplemonk.zeproc_magento_sales_creditmemo qualify row_number() over(partition by entity_id order by 1) = 1 ) AS scm ON scm.entity_id = scmi.parent_id LEFT JOIN ( select * from zeproc_db.maplemonk.zeproc_magento_sales_order_payment qualify row_number() over(partition by parent_id order by 1) = 1 ) AS sop ON sop.parent_id = soi.order_id LEFT JOIN ( select * from zeproc_db.maplemonk.zeproc_magento_sales_order_address where address_type = \'shipping\' qualify row_number() over(partition by parent_id order by 1) = 1 ) AS soa ON soa.parent_id = soi.order_id left join ( select * from zeproc_db.maplemonk.order_by_source_factitems qualify row_number() over(partition by transactionid order by 1) = 1 )tr on so.INCREMENT_ID = tr.TRANSACTIONID left join ( select * from zeproc_db.maplemonk.zeproc_catalog_product_master_final qualify row_number() over(partition by lower(sku) order by 1) = 1 )d on lower(soi.sku) = lower(d.sku) left join ( select date_start::date as date, \'FACEBOOK\' as Channel, split(product_id,\',\')[0]::String as product_id, upper(replace(campaign_name,\' \',\'\')) campaign_name, sum(ifnull(spend,0)) as Spend from zeproc_db.maplemonk.product_customcampaigns_data group by 1,2,3,4 UNION ALL Select cast(\"segments.date\" as date)Date, \'GOOGLE\' as Channel, \"segments.product_item_id\" as PRODUCT_ID, upper(replace(\"campaign.name\",\' \',\'\')) campaign_name, sum(\"metrics.cost_micros\")/1000000 spend from zeproc_db.maplemonk.zeproc_db_product_level_stream group by 1,2,3,4 ) sp on lower(soi.PRODUCT_ID::string) = lower(sp.PRODUCT_ID::string) and soi.CREATED_AT::date = sp.date::date and trim(lower(sp.channel)) = trim(lower(tr.channel)) and upper(replace(tr.SESSIONCAMPAIGNNAME,\' \',\'\')) = upper(replace(sp.campaign_name,\' \',\'\')) ;",
                    "transaction": true
                }
            ) }}
